function Fixture(){const params=new URLSearchParams(location.search);const [view,setView]=useState(params.get('view')||'home'),[action,setAction]=useState(''),[requestId,setRequestId]=useState(params.get('request'));const audit=params.get('audit')==='admin';const scope=new URLSearchParams(location.search).get('scope')||'Organisation';const act=name=>()=>setAction(name);const Screen=auditScreens[params.get('screen')];const auditProject=id=>{const next=new URL(location.href);if(id){next.searchParams.set('screen','projects');next.searchParams.set('project',id);}else next.searchParams.delete('project');history.pushState({},'',next);setAction('project:'+id);};const auditMe={...me,role:'staff',managed_units:[],memberships:[],capabilities:[...me.capabilities,'attendance.correct','payroll.prepare','payroll.approve','hr_private.access','authority.manage','audit.view','integration.manage','performance.admin','learning.manage','asset.manage'],capability_grants:[{capability:'people.manage',scope_unit_id:null},{capability:'performance.admin',scope_unit_id:null},{capability:'learning.manage',scope_unit_id:null}]};return <div className="app office-app"><SideNav me={params.get('audit')==='screen'?auditMe:me} isAdmin tab={view} setTab={setView}/><div className="ev2s-workspace"><MobileTopBar me={params.get('audit')==='screen'?auditMe:me} isAdmin roleLabel="Administration" onNavigate={setView} onOpenWork={id=>setAction('work:'+id)} onOpenProject={auditProject} onOpenPerson={person=>setAction('person:'+person.id)} onOpenRoom={room=>setAction('room:'+room.unitId)}/><AppTopBar me={params.get('audit')==='screen'?auditMe:me} isAdmin tab={view} onNavigate={setView} onOpenWork={id=>setAction('work:'+id)} onOpenProject={auditProject} onOpenPerson={person=>setAction('person:'+person.id)} onOpenRoom={room=>setAction('room:'+room.unitId)}/><main className="app-content ev2s-content"><output aria-label="Fixture action">{action}</output>{params.get('audit')==='screen'&&Screen?<Screen me={auditMe} initialProjectId={params.get('project')} openProject={auditProject} openItem={id=>setAction('work:'+id)} goAssign={act('assign')} scheduleMeeting={act('meeting')} openMeeting={act('meeting')} openExpenses={act('expenses')} go={act('navigate')} back={act('back')} openPeopleAccess={act('people')}/>:view==='attendance'&&audit?<Workforce me={params.get('access')==='limited'?{...me,capabilities:[]}:me} initialLeaveRequestId={requestId}/>:view==='attendance'?<div className="body"><TimeLeavePlanner rows={rows} scope={scope} initialRequestId={requestId} renderDecision={scope==='My'?null:r=><div><strong>{r.profiles.full_name}</strong><p>{r.status==='pending'?'Waiting for Manager approval':'Approved'}</p>{scope==='Team'&&r.status==='pending'?<button type="button" onClick={act('manager review')}>Review with Manager</button>:null}</div>} onOpenLeave={act('leave')} onOpenSessions={act('sessions')}/></div>:<AdminOverviewV2 me={me} dateLabel="Saturday 24 October" leaveQueue={rows.filter(r=>r.status==='pending').map(r=>({...r,requester:r.profiles}))} employeeRoster={roster} dailySessionRows={sessions} canManagePeople announcements={[]} reporting={{submitted:0,total:3,missing:[],label:'October'}} today={{working:2}} onOpenPeople={act('people')} onOpenSettings={act('settings')} onOpenAttendance={()=>setView('attendance')} onOpenLeaveRequest={id=>{setRequestId(id);setView('attendance');setAction('request:'+id);}} onOpenReports={act('reports')} onOpenProjects={act('projects')} onOpenFinance={act('finance')} onOpenAnnouncements={act('announcements')} onOpenPerson={act('person')} onOpenAccess={act('access')}/>}</main><Tabs me={params.get('audit')==='screen'?auditMe:me} isAdmin tab={view} setTab={setView}/></div></div>}
createRoot(document.getElementById('root')).render(<Fixture/>);
